--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: check_dining_table_section_branch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_dining_table_section_branch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN IF NEW.section_id IS NOT NULL THEN IF NOT EXISTS (SELECT 1 FROM branch_sections WHERE section_id = NEW.section_id AND branch_id = NEW.branch_id) THEN RAISE EXCEPTION 'Section khong thuoc branch cua ban'; END IF; END IF; RETURN NEW; END; $$;


ALTER FUNCTION public.check_dining_table_section_branch() OWNER TO postgres;

--
-- Name: check_employee_branch_company(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_employee_branch_company() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN IF NEW.branch_id IS NOT NULL THEN IF NEW.company_id IS NULL THEN RAISE EXCEPTION 'Employee thuoc branch thi bat buoc phai co company_id'; END IF;
    IF NOT EXISTS (SELECT 1 FROM branches WHERE branch_id = NEW.branch_id AND company_id = NEW.company_id) THEN RAISE EXCEPTION 'Branch khong thuoc company cua employee'; END IF; END IF; RETURN NEW; END; $$;


ALTER FUNCTION public.check_employee_branch_company() OWNER TO postgres;

--
-- Name: create_wallet_for_customer(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_wallet_for_customer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN INSERT INTO customer_wallets (customer_id, balance, status) VALUES (NEW.customer_id, 0, 'ACTIVE') ON CONFLICT (customer_id) DO NOTHING; RETURN NEW; END; $$;


ALTER FUNCTION public.create_wallet_for_customer() OWNER TO postgres;

--
-- Name: enforce_combo_item_company(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_combo_item_company() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM combos c
    JOIN menu_items mi ON mi.menu_item_id = NEW.menu_item_id
    WHERE c.combo_id = NEW.combo_id AND c.company_id = mi.company_id
  ) THEN
    RAISE EXCEPTION 'Combo and menu item must belong to the same company';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_combo_item_company() OWNER TO postgres;

--
-- Name: has_workspace_role(uuid, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.has_workspace_role(target_workspace_id uuid, allowed_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
    from public.memberships
    where workspace_id = target_workspace_id
      and user_id = auth.uid()
      and role = any(allowed_roles)
  );
$$;


ALTER FUNCTION public.has_workspace_role(target_workspace_id uuid, allowed_roles text[]) OWNER TO postgres;

